corrected_code:
router.post('/api/auth/renew-tenant-token', async (req, res) => {
  const { refreshToken, targetTenantId } = req.body;

  let payload;
  try {
    payload = jwt.verify(refreshToken, process.env.REFRESH_TOKEN_KEY);
  } catch (err) {
    return res.status(401).json({ error: 'Token invalid' });
  }

  const membership = await db.query(
    'SELECT role FROM tenant_memberships WHERE user_id = $1 AND tenant_id = $2 AND status = \'ACTIVE\'',
    [payload.userId, targetTenantId]
  );
  if (membership.rowCount === 0) {
    return res.status(403).json({ error: 'User is not a member of target tenant' });
  }

  const tenantToken = jwt.sign({
    userId: payload.userId,
    tenantId: targetTenantId,
    role: membership.rows[0].role,
    issuedAt: Date.now()
  }, process.env.TENANT_ACCESS_KEY, { expiresIn: '1h' });

  res.json({ tenantToken });
});
